func planOf(pl *port.Cells, pages int32, kind int32) int32 {
	// `pages` rows; every page of `kind`, with a stream at bytes 100 + 50 of the input, a box and a page size.
	var i int32 = 0
	for i < pages {
		port.CellsPush(pl, kind)
		port.CellsPush(pl, 9)
		port.CellsPush(pl, 100)
		port.CellsPush(pl, 50)
		port.CellsPush(pl, 0)
		port.CellsPush(pl, 0)
		port.CellsPush(pl, 61200)
		port.CellsPush(pl, 79200)
		port.CellsPush(pl, 61200)
		port.CellsPush(pl, 79200)
		i += 1
	}
	return 0
}

func runPage(i int32, policy int32, pl *port.Cells, ans *port.Cells, rq *port.Cells) int32 {
	return pageunit.PuRunPdf(i, 3, policy, pl, ans, rq, port.NewCells(), port.NewBitmapSet(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells())
}

func TestIdsArePerPageUnit(emonT *testing.T) {
	port.AssertEq(emonT, plan.PuId(0, plan.PiDecode()), 260, "page 0 decode")
	port.AssertEq(emonT, plan.PuId(0, plan.PiRenderText()), 257, "page 0 render with text")
	port.AssertEq(emonT, plan.PuId(41, plan.PiDecode()), 10756, "page 41 decode: 42 * 256 + 4")
	port.AssertEq(emonT, plan.PuViewId(0, 1), plan.ViewBase()+1, "a kin-made view of page 0")
	port.AssertEq(emonT, plan.PuViewId(2, 5), plan.ViewBase()+517, "and of page 2")
	port.AssertThat(emonT, plan.ViewBase() > plan.PuId(60000, 255), "no request id reaches the views' range")
}

func TestAScannedPagesUnitAsksForItsStreamUnderItsOwnId(emonT *testing.T) {
	var pl *port.Cells = port.NewCells()
	var rq *port.Cells = port.NewCells()
	planOf(pl, 3, pageunit.PkScan())
	port.AssertEq(emonT, runPage(1, 2, pl, port.NewCells(), rq), plan.UsRequests(), "it asks")
	port.AssertEq(emonT, plan.RecKind(rq, 0), plan.PkDecode(), "a decode")
	port.AssertEq(emonT, plan.RecId(rq, 0), 516, "page 1: 2 * 256 + 4")
	port.AssertEq(emonT, plan.RqArg(rq, 0, 0), 3, "of input 3")
	port.AssertEq(emonT, plan.RqArg(rq, 0, 1), 100, "the stream's start")
	port.AssertEq(emonT, plan.RqArg(rq, 0, 2), 50, "and length")
	port.AssertEq(emonT, plan.RqArg(rq, 0, 3), plan.FltDct(), "a DCT stream")
}

func TestAUnitWithNoAnswersAsksTheSameEveryTime(emonT *testing.T) {
	var pl *port.Cells = port.NewCells()
	var rq1 *port.Cells = port.NewCells()
	var rq2 *port.Cells = port.NewCells()
	planOf(pl, 2, pageunit.PkScan())
	runPage(0, 2, pl, port.NewCells(), rq1)
	runPage(0, 2, pl, port.NewCells(), rq2)
	port.AssertEq(emonT, port.CellsLen(rq1), port.CellsLen(rq2), "the same length")
	port.AssertEq(emonT, port.CellsAt(rq1, 2), port.CellsAt(rq2, 2), "the same id")
	port.AssertEq(emonT, port.CellsAt(rq1, 4), port.CellsAt(rq2, 4), "the same arguments")
}

func TestABornDigitalPageAndTheNeverPolicyAskNothing(emonT *testing.T) {
	var pl *port.Cells = port.NewCells()
	var rq *port.Cells = port.NewCells()
	planOf(pl, 1, pageunit.PkBorn())
	port.AssertEq(emonT, runPage(0, 2, pl, port.NewCells(), rq), plan.UsDone(), "born digital: done")
	port.AssertEq(emonT, port.CellsLen(rq), 0, "no request")
	var plan2 *port.Cells = port.NewCells()
	var rq2 *port.Cells = port.NewCells()
	planOf(plan2, 1, pageunit.PkScan())
	port.AssertEq(emonT, runPage(0, 0, plan2, port.NewCells(), rq2), plan.UsDone(), "never: done")
	port.AssertEq(emonT, port.CellsLen(rq2), 0, "no request")
	var plan3 *port.Cells = port.NewCells()
	var rq3 *port.Cells = port.NewCells()
	planOf(plan3, 1, pageunit.PkNone())
	port.AssertEq(emonT, runPage(0, 2, plan3, port.NewCells(), rq3), plan.UsDone(), "no image: done")
	port.AssertEq(emonT, port.CellsLen(rq3), 0, "no request")
}

func TestTheBitmapSetKeepsWhatKinMakes(emonT *testing.T) {
	var s *port.BitmapSet = port.NewBitmapSet()
	port.AssertEq(emonT, port.BmsHas(s, 5), 0, "empty")
	port.AssertEq(emonT, port.BitmapW(port.BmsGet(s, 5)), 0, "an absent bitmap is 0 x 0")
	port.AssertEq(emonT, port.BitmapH(port.BmsGet(s, 5)), 0, "in both directions")
	var b *port.Bitmap = port.BmsPut(s, plan.ViewBase(), 4, 3, 1)
	port.AssertEq(emonT, port.BmsHas(s, plan.ViewBase()), 1, "put")
	port.AssertEq(emonT, port.BitmapW(b), 4, "its width")
	port.AssertEq(emonT, port.BitmapH(b), 3, "its height")
	port.AssertEq(emonT, port.BitmapChannels(b), 1, "its channels")
	port.AssertEq(emonT, port.BitmapU8(b, 1, 1, 0), 0, "zeroed")
	port.BitmapSetU8(b, 1, 1, 0, 200)
	port.AssertEq(emonT, port.BitmapU8(port.BmsGet(s, plan.ViewBase()), 1, 1, 0), 200, "the set holds the very bitmap kin filled")
	port.AssertEq(emonT, port.BmsHas(s, plan.ViewBase()+1), 0, "another id is absent")
}
